spec:
Consider the following adder-subtractor with a zero flag:

  module TopModule (
      input      cpu_overheated,
      output reg shut_off_computer,
      input      arrived,
      input      gas_tank_empty,
      output reg keep_driving
  );

      always @(*) begin
          if (cpu_overheated)
             shut_off_computer = 1;
      end

      always @(*) begin
          if (~arrived)
             keep_driving = ~gas_tank_empty;
      end

  endmodule

Unfortunately, this module has a bug. Implement a new version of this
module that fixes the bug.

input.code:
module tb;
    reg cpu_overheated;
    wire shut_off_computer;
    reg arrived;
    reg gas_tank_empty;
    wire keep_driving;

    TopModule dut (
        .cpu_overheated(cpu_overheated),
        .shut_off_computer(shut_off_computer),
        .arrived(arrived),
        .gas_tank_empty(gas_tank_empty),
        .keep_driving(keep_driving)
    );

    initial begin
        // Test all combinations
        integer i;
        for (i = 0; i < 8; i = i + 1) begin
            {cpu_overheated, arrived, gas_tank_empty} = i[2:0];
            #1;
            // Expected
            // shut_off_computer = cpu_overheated
            // keep_driving = (~arrived) & (~gas_tank_empty)
            if (shut_off_computer !== cpu_overheated) begin
                $display("SELFFAIL: cpu_overheated=%b, shut_off_computer=%b (expected %b)", cpu_overheated, shut_off_computer, cpu_overheated);
                $finish;
            end
            if (keep_driving !== ((~arrived) & (~gas_tank_empty))) begin
                $display("SELFFAIL: arrived=%b, gas_tank_empty=%b, keep_driving=%b (expected %b)", arrived, gas_tank_empty, keep_driving, ((~arrived) & (~gas_tank_empty)));
                $finish;
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
